// Typed access to the curated local-LLM catalog (data/local-llm-catalog.json)
// and the hardware profiles (data/hardware-profiles.json), plus the glue that
// answers "does this model fit this machine".
//
// The catalog is generated by scripts/catalog-build.mjs from primary sources
// (Ollama registry manifest + GGUF header) and gated by scripts/validate-catalog.mjs.
// It is bundled at build time like every other MCP data source: nothing is
// fetched at request time.

import catalogJson from '../../data/local-llm-catalog.json'
import hardwareJson from '../../data/hardware-profiles.json'
import { fitModel, macUsableGb, type FitResult, type KvArch } from './vram'

export type CatalogTier = 'tiny' | 'small' | 'mid' | 'large' | 'xl'
export type CatalogUseCase = 'chat' | 'code' | 'agent' | 'docs' | 'image' | 'audio' | 'phone'

export interface CatalogQuant {
  name: string
  ollama_tag: string
  default: boolean
  /** Exact bytes of the weights Ollama downloads (excl. projector). */
  size_bytes: number
  /** Vision projector bytes loaded alongside the weights (0 if none). */
  projector_bytes: number
  source_url: string
  verified_date: string
}

export interface CatalogKvGroup {
  layers: number
  kv_heads: number
  key_length: number
  value_length: number
  /** Sliding-window size in tokens, or null for full attention. */
  window_tokens: number | null
}

export interface CatalogKv {
  arch: string
  layers_total: number
  groups: CatalogKvGroup[]
  /** 'modeled' = header fully describes the layers; 'upper-bound' = full attention assumed (conservative). */
  exactness: 'modeled' | 'upper-bound'
  exactness_note: string
  expert_count: number | null
  expert_used_count: number | null
  basis: 'gguf-header'
  source_url: string
}

export interface CatalogModel {
  id: string
  registry_model: string
  family: string
  company: string
  variant: string
  params_b: number
  active_params_b: number | null
  active_params_source: string | null
  context_max: number
  license: string
  license_source: string
  capabilities: { vision: boolean; tools: boolean; reasoning: boolean; coding: boolean; embedding: boolean }
  capabilities_basis: 'chat-template' | 'ollama-family-badges'
  runtimes: { ollama: string }
  quants: CatalogQuant[]
  kv: CatalogKv | null
  tier: CatalogTier
  best_for: CatalogUseCase[]
  rank: { ollama_popularity_rank: number; ranked_on: string; basis: string }
  verified_date: string
  source_url: string
}

export interface LocalLlmCatalog {
  schema_version: 1
  last_updated: string
  models: CatalogModel[]
}

export type HardwareKind = 'mac-unified' | 'discrete-gpu' | 'cpu-ram'

export interface HardwareProfile {
  id: string
  label: string
  kind: HardwareKind
  total_gb: number
  reserve_gb?: number
  reserve_basis?: string
}

// JSON imports are widened by TypeScript (string literals become string), so the
// shape is asserted here; scripts/validate-catalog.mjs enforces it at build time.
export const localLlmCatalog = catalogJson as unknown as LocalLlmCatalog
export const hardwareProfiles = (hardwareJson as unknown as { profiles: HardwareProfile[] }).profiles

export function getCatalogModel(id: string): CatalogModel | undefined {
  return localLlmCatalog.models.find((m) => m.id === id)
}

export function getHardwareProfile(id: string): HardwareProfile | undefined {
  return hardwareProfiles.find((p) => p.id === id)
}

/** Anything with a memory kind and size: a fixed profile or an arbitrary machine from tool input. */
export type MemorySystem = Pick<HardwareProfile, 'kind' | 'total_gb' | 'reserve_gb'>

/** Memory (GiB) a model may use on this machine class. Mac uses the single owner rule in vram.ts. */
export function usableGibFor(system: MemorySystem): number {
  if (system.kind === 'mac-unified') return macUsableGb(system.total_gb)
  return Math.max(system.total_gb - (system.reserve_gb ?? 0), 0)
}

function reserveFor(kind: Exclude<HardwareKind, 'mac-unified'>): number {
  // Single source: the first profile of that kind in data/hardware-profiles.json.
  return hardwareProfiles.find((p) => p.kind === kind)?.reserve_gb ?? 0
}

/**
 * Same input convention as the other directory tools: on a Mac the caller passes TOTAL unified
 * memory (as ramGb) and the 8 GB macOS reserve is deducted here, exactly once. On Windows/Linux a
 * given vramGb means a discrete GPU; otherwise ramGb means CPU-only system RAM.
 * Returns null when no memory was given.
 */
export function systemFromInputs(args: { os?: string; ramGb?: number; vramGb?: number }): { system: MemorySystem; label: string } | null {
  if (args.os === 'mac') {
    const total = args.ramGb ?? args.vramGb
    return total ? { system: { kind: 'mac-unified', total_gb: total }, label: `Mac, ${total} GB unified memory` } : null
  }
  if (args.vramGb) {
    return { system: { kind: 'discrete-gpu', total_gb: args.vramGb, reserve_gb: reserveFor('discrete-gpu') }, label: `GPU with ${args.vramGb} GB VRAM` }
  }
  if (args.ramGb) {
    return { system: { kind: 'cpu-ram', total_gb: args.ramGb, reserve_gb: reserveFor('cpu-ram') }, label: `CPU-only, ${args.ramGb} GB RAM` }
  }
  return null
}

export function defaultQuant(model: CatalogModel): CatalogQuant {
  return model.quants.find((q) => q.default) ?? model.quants[0]
}

function toKvArch(kv: CatalogKv | null): KvArch | null {
  return kv
    ? {
        groups: kv.groups.map((g) => ({
          layers: g.layers,
          kvHeads: g.kv_heads,
          keyLength: g.key_length,
          valueLength: g.value_length,
          windowTokens: g.window_tokens,
        })),
      }
    : null
}

export interface ModelFit extends FitResult {
  /** 'modeled' or 'upper-bound' (KV assumed full attention); null for embedding models. */
  kvExactness: CatalogKv['exactness'] | null
  modelId: string
  quant: string
  contextTokens: number
  ollamaPull: string
}

/**
 * Does `model` (default quantization unless one is named) fit `system` at `contextTokens`?
 * contextTokens is clamped to the model's own maximum.
 */
export function fitCatalogModel(model: CatalogModel, system: MemorySystem, contextTokens: number, quantName?: string): ModelFit {
  const quant = (quantName ? model.quants.find((q) => q.name === quantName) : undefined) ?? defaultQuant(model)
  const ctx = Math.min(contextTokens, model.context_max)
  const fit = fitModel({
    sizeBytes: quant.size_bytes + quant.projector_bytes,
    kv: toKvArch(model.kv),
    noContextCost: model.capabilities.embedding,
    contextTokens: ctx,
    contextMax: model.context_max,
    usableGib: usableGibFor(system),
  })
  return {
    ...fit,
    kvExactness: model.kv?.exactness ?? null,
    modelId: model.id,
    quant: quant.name,
    contextTokens: ctx,
    ollamaPull: `ollama pull ${model.family}:${quant.ollama_tag}`,
  }
}
